e — and Select''s comment records that as the tier''s choice.","tree":{"sha":"1b78237a31bb4419abe8da154e1549917c89fedd","url":"https://api.github.com/repos/juansrodz/calcifer-design/git/trees/1b78237a31bb4419abe8da154e1549917c89fedd"},"url":"https://api.github.com/repos/juansrodz/calcifer-design/git/commits/43ca7da28da32435d17566179a87e03b9b732e2a","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/26170268?v=4","events_url":"https://api.github.com/users/juansrodz/events{/privacy}","followers_url":"https://api.github.com/users/juansrodz/followers","following_url":"https://api.github.com/users/juansrodz/following{/other_user}","gists_url":"https://api.github.com/users/juansrodz/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/juansrodz","id":26170268,"login":"juansrodz","node_id":"MDQ6VXNlcjI2MTcwMjY4","organizations_url":"https://api.github.com/users/juansrodz/orgs","received_events_url":"https://api.github.com/users/juansrodz/received_events","repos_url":"https://api.github.com/users/juansrodz/repos","site_admin":false,"starred_url":"https://api.github.com/users/juansrodz/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/juansrodz/subscriptions","type":"User","url":"https://api.github.com/users/juansrodz","user_view_type":"public"},"html_url":"https://github.com/juansrodz/calcifer-design/commit/43ca7da28da32435d17566179a87e03b9b732e2a","node_id":"C_kwDOURhjnNoAKDQzY2E3ZGEyOGRhMzI0MzVkMTc1NjYxNzlhODdlMDNiOWI3MzJlMmE","parents":[{"html_url":"https://github.com/juansrodz/calcifer-design/commit/01888bfb7604305f9fcedbc85d22f973d0ddb42c","sha":"01888bfb7604305f9fcedbc85d22f973d0ddb42c","url":"https://api.github.com/repos/juansrodz/calcifer-design/commits/01888bfb7604305f9fcedbc85d22f973d0ddb42c"}],"sha":"43ca7da28da32435d17566179a87e03b9b732e2a","url":"https://api.github.com/repos/juansrodz/calcifer-design/commi